    let parseCalled = false;
    ms.parse = function(val) {
      parseCalled = true;
      return originalParse(val);
    };

    // Now call ms with a number
    ms(123);

    // In the original, parse should not be called
    // In the patched version, parse IS called because of the `true && val.length > 0` condition
    // So parseCalled should be true in patched, false in original
    assert.strictEqual(parseCalled, false, 'parse should not be called on numbers in original');

