    let originalWorks = false;
    let patchedFails = false;

    try {
      assert.strictEqual(ms(123), '123ms');
      originalWorks = true;
    } catch (e) {
      // original should not throw
      assert.fail('original should not throw');
    }

    try {
      ms(123);
      // if we get here, patched didn't throw
      assert.fail('patched should throw on number input');
    } catch (e) {
      if (e instanceof TypeError) {
        patchedFails = true;
      } else {
        assert.fail('patched should throw TypeError');
      }
    }

    // Now we know original works and patched fails
    // But we need to write a test that passes on original and fails on patched
    // So we can just assert that ms(123) is '123ms' in original
    // And in patched, it throws, so the assertion will fail

